/* Ox Arcade — frontend */
"use strict";

const $ = (sel) => document.querySelector(sel);
// Base path for reverse-proxy subpath deployments ("/OxArcade" etc.).
// config.js is generated by the server from its BASE_PATH env.
const BASE = (window.OX_CONFIG && window.OX_CONFIG.basePath || "").replace(/\/+$/, "");
const withBase = (p) => p.startsWith("/") ? BASE + p : BASE + "/" + p;
const grid = $("#grid");
const tpl = $("#card-tpl");

const state = {
  builds: [],
  hzMeta: {},
  filter: "all",
  view: "grid",
  query: "",
  overlayId: null,
};

const fmtBytes = (n) => {
  if (!n) return "—";
  const u = ["B", "KB", "MB", "GB"];
  let i = 0;
  while (n >= 1024 && i < u.length - 1) { n /= 1024; i++; }
  return `${n.toFixed(n >= 100 || i === 0 ? 0 : 1)} ${u[i]}`;
};
const fmtWhen = (iso) => {
  if (!iso) return "unknown";
  const d = new Date(iso);
  const mins = Math.round((Date.now() - d.getTime()) / 60000);
  if (mins < 2) return "just now";
  if (mins < 60) return `${mins}m ago`;
  const hrs = Math.round(mins / 60);
  if (hrs < 24) return `${hrs}h ago`;
  return d.toLocaleDateString(undefined, { month: "short", day: "numeric" });
};

async function load() {
  const res = await fetch(withBase("/api/builds"));
  const body = await res.json();
  state.hzMeta = body.harnessMeta || {};
  state.arcadeEnabled = !!(body.arcade && body.arcade.enabled);

  // local builds + (when syncing) remote repo games in one list
  const remotes = (body.arcade && body.arcade.games ? body.arcade.games : [])
    .map((g) => ({
      id: "r-" + g.route.toLowerCase().replace(/[^a-z0-9]+/g, "-"),
      remote: true,
      route: g.route,
      dir: g.route,
      title: g.title,
      description: g.description,
      model: g.model,
      entry: g.entry,
      status: g.deployed ? "playable" : "undeployed",
      url: g.url,                 // same-origin path served by this site
      deployedUrl: g.deployed,
      thumb: g.thumb || withBase(`/thumbs/${encodeURIComponent(g.route)}.png`),
      mtime: g.mtime,
      sizeBytes: 0,
      fileCount: 0,
      tags: g.deployed ? ["remote", "game"] : ["remote", "undeployed"],
      shots: [],
      harness: g.harness,
      multiplayer: g.multiplayer || null,
    }));

  state.builds = [...body.builds, ...remotes];
  $("#count").textContent = `${body.count} exhibits` +
    (remotes.length ? ` + ${remotes.length} remote` : "");
  const syncBtn = $("#sync-btn");
  if (syncBtn) syncBtn.hidden = !state.arcadeEnabled;
  renderHzChips();
  renderHero();
  render();
}

/* Harness chips + badges are rendered purely from the API registry —
   adding a future harness needs zero frontend edits. */
function renderHzChips() {
  const nav = $("#hz-chips");
  if (!nav) return;
  nav.innerHTML = "";
  for (const [key, meta] of Object.entries(state.hzMeta)) {
    const btn = document.createElement("button");
    btn.className = "chip";
    btn.dataset.filter = `hz:${key}`;
    btn.title = meta.label;
    const dot = document.createElement("span");
    dot.className = "dot";
    dot.style.background = meta.color;
    btn.appendChild(dot);
    btn.appendChild(document.createTextNode(meta.label));
    nav.appendChild(btn);
  }
}
function hzOf(b) { return b && b.harness && b.harness !== "none" ? b.harness : null; }

function visibleBuilds() {
  const q = state.query.toLowerCase();
  return state.builds.filter((b) => {
    let tagOk;
    if (state.filter.startsWith("hz:")) {
      tagOk = ("hz:" + (b.harness || "none")) === state.filter;
    } else if (state.filter === "all") {
      tagOk = true;
    } else if (state.filter === "incomplete") {
      tagOk = b.status === "incomplete";
    } else if (state.filter === "multiplayer") {
      tagOk = !!(b.multiplayer && b.multiplayer.supported);
    } else {
      tagOk = b.tags.includes(state.filter);
    }
    if (!tagOk) return false;
    if (!q) return true;
    return (
      b.title.toLowerCase().includes(q) ||
      (b.description || "").toLowerCase().includes(q) ||
      b.tags.some((t) => t.includes(q))
    );
  });
}

function render() {
  const list = visibleBuilds();
  grid.innerHTML = "";
  grid.classList.toggle("strip", state.view === "strip");
  $("#empty").hidden = list.length > 0;

  list.forEach((b, i) => {
    const node = tpl.content.firstElementChild.cloneNode(true);
    node.dataset.id = b.id;
    node.style.animationDelay = `${Math.min(i, 12) * 45}ms`;
    if (b.status === "incomplete") node.classList.add("incomplete");

    const img = node.querySelector(".thumb img");
    img.alt = b.title;
    img.src = b.thumb;
    img.addEventListener("load", () => node.querySelector(".thumb").classList.add("has-img"));
    img.addEventListener("error", () => { img.removeAttribute("src"); });

    const ribbon = node.querySelector(".ribbon");
    const st = b.buildStatus;
    if (b.status === "incomplete") {
      ribbon.textContent = "INCOMPLETE";
    } else if (st && st.status === "done") {
      ribbon.textContent = "DONE";
      ribbon.classList.add("green");
    } else if (st && st.status === "inprogress") {
      ribbon.textContent = "IN PROGRESS";
      ribbon.classList.add("amber");
    } else if (b.remote && b.status === "undeployed") {
      ribbon.textContent = "UNDEPLOYED";
      ribbon.classList.add("muted");
    } else if (b.remote) {
      ribbon.textContent = "REMOTE";
      ribbon.classList.add("green");
    } else {
      ribbon.textContent = b.status === "playable" ? "PLAYABLE" : "INCOMPLETE";
    }

    // harness badge — data-driven, per-card accent color
    const hz = hzOf(b);
    const meta = hz ? state.hzMeta[hz] : null;
    const badge = node.querySelector(".hz-badge");
    if (meta) {
      node.dataset.harness = hz;
      node.style.setProperty("--hz", meta.color);
      badge.querySelector(".glyph").textContent = meta.glyph;
      badge.querySelector(".hz-name").textContent = meta.label;
      badge.hidden = false;
    } else {
      badge.hidden = true;
    }

    // multiplayer badge — shown when netcode was detected or declared
    const mpBadge = node.querySelector(".mp-badge");
    if (mpBadge) {
      const mp = b.multiplayer;
      if (mp && mp.supported) {
        mpBadge.hidden = false;
        mpBadge.title = "Online-capable (" + mp.signals.join(", ") + ")" +
          (mp.endpoint ? " \u00b7 " + mp.endpoint : "");
      } else {
        mpBadge.hidden = true;
      }
    }

    node.querySelector(".c-title").textContent = b.title;
    node.querySelector(".c-desc").textContent = b.description || "No description on file.";
    const sizePart = b.remote ? "" : ` · ${fmtBytes(b.sizeBytes)} · ${b.fileCount} files`;
    node.querySelector(".c-time").textContent = `touched ${fmtWhen(b.mtime)}${sizePart}`;
    node.querySelector(".c-tags").textContent = b.tags.join(" · ");

    attachLivePreview(node, b);
    node.addEventListener("click", () => openOverlay(b.id));
    node.addEventListener("keydown", (e) => { if (e.key === "Enter") openOverlay(b.id); });
    grid.appendChild(node);
  });
}

/* Hover a card 600ms -> swap the screenshot for a live muted iframe. One at a time. */
let liveTimer = null, liveEl = null;
function destroyLive() {
  clearTimeout(liveTimer); liveTimer = null;
  if (liveEl) { liveEl.remove(); liveEl = null; }
}
function attachLivePreview(card, b) {
  if (b.status !== "playable") return;
  const holder = card.querySelector(".live-holder");
  card.addEventListener("mouseenter", () => {
    liveTimer = setTimeout(async () => {
      if (!(await probeBuild(b))) return; // dead build: keep the screenshot
      destroyLive();
      const f = document.createElement("iframe");
      f.src = b.url; f.title = b.title;
      f.setAttribute("allow", "autoplay");
      f.setAttribute("sandbox", "allow-scripts allow-same-origin");
      holder.appendChild(f);
      holder.classList.add("on");
      card.querySelector(".thumb").classList.add("live");
      liveEl = holder;
    }, 600);
  });
  card.addEventListener("mouseleave", destroyLive);
}

/* ---------- hero ---------- */
function renderHero() {
  const newest = [...state.builds]
    .filter((b) => b.status === "playable")
    .sort((a, b) => (b.mtime || "").localeCompare(a.mtime || ""))[0];
  const hero = $("#hero");
  if (!newest) { hero.hidden = true; return; }
  hero.hidden = false;
  hero.dataset.id = newest.id;
  $("#hero-img").src = newest.thumb;
  $("#hero-title").textContent = newest.title;
  $("#hero-desc").textContent = newest.description || "Fresh out of a goal loop.";
  const heroHz = hzOf(newest);
  $(".hero .eyebrow").textContent =
    "LATEST EXHIBIT" + (heroHz && state.hzMeta[heroHz] ? " · " + state.hzMeta[heroHz].label : "");
  $("#hero-play").onclick = () => openOverlay(newest.id);
  $("#hero-folder").onclick = () => reveal(newest.id);
}

/* ---------- overlay ---------- */
const headProbeCache = new Map(); // id -> true(loads) / false(broken)
async function probeBuild(b) {
  if (!b.url) return false;
  if (headProbeCache.has(b.id)) return headProbeCache.get(b.id);
  let ok = false;
  try {
    const r = await fetch(b.url, { method: "HEAD" });
    ok = r.ok;
  } catch { ok = false; }
  headProbeCache.set(b.id, ok);
  return ok;
}

function setOvNote(text, showFolder) {
  const note = $("#ov-note");
  note.textContent = text;
  note.hidden = false;
  $("#ov-folder").style.display = showFolder ? "" : "none";
}

function mountGameFrame(url) {
  const frame = $("#ov-frame");
  frame.hidden = false;
  frame.style.display = "";
  frame.src = url;
}
function openOverlay(id) {
  const b = state.builds.find((x) => x.id === id);
  if (!b) return;
  state.overlayId = id;

  $("#ov-title").textContent = b.title;
  $("#ov-desc").textContent = b.description || "No description on file.";

  const meta = $("#ov-meta");
  const hz = hzOf(b);
  const hzLabel = hz && state.hzMeta[hz] ? state.hzMeta[hz].label : "—";
  const mp = b.multiplayer;
  const bst = b.buildStatus;
  meta.innerHTML = `
    <dt>STATUS</dt><dd>${b.status}</dd>
    ${bst ? `<dt>BUILD</dt><dd>${bst.status} · checks ${bst.checks}</dd>` : ""}
    <dt>HARNESS</dt><dd class="mono">${hzLabel}</dd>
    ${b.model ? `<dt>MODEL</dt><dd class="mono">${b.model}</dd>` : ""}
    <dt>NETCODE</dt><dd class="mono">${mp && mp.supported ? mp.signals.join(" + ") + (mp.endpoint ? " · " + mp.endpoint : "") : "single-player"}</dd>
    <dt>ENTRY</dt><dd class="mono">${b.entry || "—"}</dd>
    <dt>FOLDER</dt><dd class="mono">${b.dir}</dd>
    <dt>SIZE</dt><dd>${fmtBytes(b.sizeBytes)} · ${b.fileCount} files</dd>
    <dt>TOUCHED</dt><dd>${new Date(b.mtime).toLocaleString()}</dd>`;
  meta.querySelectorAll("dd").forEach((el) => {
    el.textContent = el.textContent; // defuse any html from names
  });

  const gal = $("#ov-gallery");
  gal.innerHTML = "";
  if (b.shots && b.shots.length) {
    for (const s of b.shots.slice(0, 8)) {
      const im = document.createElement("img");
      im.loading = "lazy"; im.src = s; im.alt = "screenshot";
      gal.appendChild(im);
    }
  } else {
    gal.innerHTML = `<div class="g-empty">no in-game screenshots found</div>`;
  }

  const frame = $("#ov-frame");
  const note = $("#ov-note");
  frame.hidden = true;
  frame.style.display = "none";
  frame.removeAttribute("src");
  note.hidden = true;
  $("#ov-folder").style.display = "";
  if (b.status !== "playable" || !b.entry) {
    const noteText = b.remote && b.status === "undeployed"
      ? "Waiting for the server agent to deploy this build."
      : "No HTML entry found in this build.";
    setOvNote(noteText, true);
  } else {
    // truth before beauty: probe the files, then mount
    mountGameFrame(b.url);
    probeBuild(b).then((ok) => {
      if (state.overlayId !== b.id) return;      // user moved on
      if (!ok) {
        frame.src = "about:blank";
        setOvNote(b.remote
          ? "Couldn't load this remote game right now."
          : "Couldn't load the game files — this build may need its own dev server. Use Open folder to run it locally.", true);
      }
    });
  }
  // remote + deployed games also get a "PLAY REMOTE ↗" action
  const popBtn = $("#ov-pop");
  popBtn.onclick = () => {
    if (!b) return;
    window.open(b.deployedUrl || b.url, "_blank");
  };
  popBtn.textContent = b.deployedUrl ? "\u2197 Play remote" : "\u2197 Pop out";

  $("#ov-folder").onclick = () => reveal(b.id);
  $("#ov-regen").onclick = async (e) => {
    const btn = e.currentTarget;
    btn.disabled = true; btn.textContent = "Regenerating…";
    try {
      await fetch(withBase(`/api/thumb/${b.id}`), { method: "POST" });
      // bust caches
      $("#hero-img").src = withBase(`/thumbs/${b.id}.png?${Date.now()}`);
      document.querySelectorAll(`.card[data-id="${b.id}"] .thumb img`)
        .forEach((im) => { im.src = withBase(`/thumbs/${b.id}.png?${Date.now()}`); });
    } finally {
      btn.disabled = false; btn.textContent = "Regenerate thumbnail";
    }
  };

  $("#overlay").hidden = false;
  document.body.style.overflow = "hidden";
}
function closeOverlay() {
  $("#overlay").hidden = true;
  $("#ov-frame").removeAttribute("src");
  document.body.style.overflow = "";
  state.overlayId = null;
}

function reveal(id) {
  fetch(`/api/reveal/${id}`, { method: "POST" });
}

/* ---------- controls ---------- */
let searchT = null;
$("#search").addEventListener("input", (e) => {
  clearTimeout(searchT);
  searchT = setTimeout(() => { state.query = e.target.value.trim(); render(); }, 120);
});
// One delegated handler for every chip rail (#chips, #hz-chips, …) — chips
// created later are covered automatically.
document.addEventListener("click", (e) => {
  const chip = e.target.closest(".chip");
  if (!chip || chip.dataset.filter === undefined) return;
  document.querySelectorAll(".chip").forEach((c) => c.classList.toggle("active", c === chip));
  state.filter = chip.dataset.filter;
  render();
});
$("#viewtoggle").addEventListener("click", (e) => {
  const btn = e.target.closest("button");
  if (!btn) return;
  document.querySelectorAll("#viewtoggle button").forEach((x) => x.classList.toggle("active", x === btn));
  state.view = btn.dataset.view;
  render();
});
$("#ov-close").addEventListener("click", closeOverlay);
$("#ov-backdrop").addEventListener("click", closeOverlay);
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && !$("#overlay").hidden) closeOverlay();
});
$("#ov-reload").addEventListener("click", () => {
  const f = $("#ov-frame"); const src = f.src; f.src = ""; setTimeout(() => { f.src = src; }, 60);
});
$("#ov-pop").addEventListener("click", () => {
  const b = state.builds.find((x) => x.id === state.overlayId);
  if (b && b.status === "playable") window.open(b.url, "_blank");
});
$("#ov-fs").addEventListener("click", () => {
  $("#ov-stage").requestFullscreen?.().catch(() => {});
});
$("#sync-btn").addEventListener("click", async (e) => {
  const btn = e.currentTarget;
  btn.disabled = true;
  const old = btn.textContent;
  btn.textContent = "⟳ Syncing…";
  try {
    await fetch(withBase("/api/sync"), { method: "POST" });
    await load();
  } finally {
    btn.disabled = false;
    btn.textContent = old;
  }
});
/* ---------- starfield ---------- */
(function starfield() {
  const cv = document.getElementById("stars");
  if (!cv || matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  const ctx = cv.getContext("2d");
  let W, H, stars = [], mx = 0, my = 0;
  const N = 140;
  function resize() {
    W = cv.width = innerWidth; H = cv.height = innerHeight;
    stars = Array.from({ length: N }, () => ({
      x: Math.random() * W, y: Math.random() * H,
      r: Math.random() * 1.3 + 0.3,
      vx: (Math.random() - 0.5) * 0.06,
      vy: (Math.random() - 0.5) * 0.06,
      a: Math.random() * 0.5 + 0.25,
    }));
  }
  addEventListener("resize", resize); resize();
  addEventListener("pointermove", (e) => {
    mx = (e.clientX / W - 0.5) * 12; my = (e.clientY / H - 0.5) * 12;
  });
  let running = true;
  document.addEventListener("visibilitychange", () => { running = !document.hidden; });
  (function frame() {
    requestAnimationFrame(frame);
    if (!running) return;
    ctx.clearRect(0, 0, W, H);
    for (const s of stars) {
      s.x += s.vx; s.y += s.vy;
      if (s.x < 0) s.x += W; if (s.x > W) s.x -= W;
      if (s.y < 0) s.y += H; if (s.y > H) s.y -= H;
      ctx.globalAlpha = s.a;
      ctx.fillStyle = "#cfe0ff";
      ctx.beginPath();
      ctx.arc(s.x + mx * (s.r / 1.6), s.y + my * (s.r / 1.6), s.r, 0, 7);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  })();
})();

/* ---------- boot sequence ---------- */
(function boot() {
  const el = document.getElementById("boot");
  if (!el) return;
  const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const done = () => el.classList.add("done");
  if (reduced || sessionStorage.getItem("ga-booted") || new URLSearchParams(location.search).has("noboot")) { done(); return; }
  sessionStorage.setItem("ga-booted", "1");
  const lines = ["OX ARCADE", "INDEXING EXHIBITS… OK", "READY_"];
  const pre = document.getElementById("boot-text");
  let li = 0, ci = 0;
  const skip = () => { done(); cleanup(); };
  function cleanup() {
    el.removeEventListener("click", skip);
    removeEventListener("keydown", keySkip);
  }
  function keySkip(e) { if (e.key === "Escape") skip(); }
  el.addEventListener("click", skip);
  addEventListener("keydown", keySkip);
  setTimeout(() => {
    (function type() {
      if (li >= lines.length) { setTimeout(() => { done(); cleanup(); }, 260); return; }
      const line = lines[li];
      if (ci < line.length) {
        pre.textContent = lines.slice(0, li).join("\n") + "\n" + line.slice(0, ++ci);
        setTimeout(type, line.startsWith("INDEXING") ? 16 : 34);
      } else { li++; ci = 0; setTimeout(type, 130); }
    })();
  }, 150);
})();

/* ---------- keyboard shortcuts ---------- */
addEventListener("keydown", (e) => {
  const typing = /^(INPUT|TEXTAREA)$/.test(document.activeElement?.tagName || "");
  if (e.key === "/" && !typing) { e.preventDefault(); $("#search").focus(); }
  else if (e.key === "Escape" && typing && !$("#search").value) { $("#search").blur(); }
  else if ((e.key === "g" || e.key === "G") && !typing) {
    const btn = document.querySelector(`#viewtoggle button[data-view="${state.view === "grid" ? "strip" : "grid"}"]`);
    btn?.click();
  }
});

load();
